parameters.jsCode:
// Extract data from merged inputs
const item1 = $input.first().json;
const item2 = $input.last().json;

let companies = [];
let jobTitles = [];

// Check which item has which data
if (item1.output && item1.output.companies) {
  companies = item1.output.companies.map(x => x.name);
}
if (item2.output && item2.output.companies) {
  companies = item2.output.companies.map(x => x.name);
}

if (item1.output && item1.output.job_titles) {
  jobTitles = item1.output.job_titles;
}
if (item2.output && item2.output.job_titles) {
  jobTitles = item2.output.job_titles;
}

// Format as text
const companiesText = companies.join(', ');
const jobTitlesText = jobTitles.join(', ');

return [{
  json: {
    companies_text: companiesText,
    job_titles_text: jobTitlesText,
    companies_array: companies,
    job_titles_array: jobTitles
  }
}];

